<h1><?= $v->e($v->t($title)) ?></h1>
<?php if (\FluxFiles\LicenseServer\Client\Config::sandbox()): ?><p class="pill test"><?= $v->e($v->t('test_data')) ?></p><?php endif ?>
<?php if (!in_array($kind,['versions','anomalies'],true)): ?><form class="card filters" method="get"><label><?= $v->e($v->t('from')) ?><input type="date" name="from" value="<?= $v->e($_GET['from']??date('Y-m-01',strtotime('-11 months'))) ?>"></label><label><?= $v->e($v->t('to')) ?><input type="date" name="to" value="<?= $v->e($_GET['to']??date('Y-m-d')) ?>"></label><button><?= $v->e($v->t('filter')) ?></button></form><?php endif ?>
<?php if ($kind==='customers'): ?><section class="card"><?= \FluxFiles\LicenseServer\Admin\Svg::bar($data['series'],'month','new',$v->t('new_customers'),$v->t('data_table')) ?><?= $v->table($data['series']) ?></section><section class="card"><?= \FluxFiles\LicenseServer\Admin\Svg::heatTable($data['cohorts'],'cohort','rate',$v->t('retention'),$v->t('data_table')) ?></section>
<?php elseif ($kind==='versions'): ?><?php foreach (array_unique(array_column($data['components'],'component')) as $component): ?><section class="card"><h2><?= $v->e($component) ?></h2><?= \FluxFiles\LicenseServer\Admin\Svg::horizontal(array_map(static fn(array $r):array=>array_merge($r,['version'=>$r['version']??$v->t('unknown_affected')]),array_values(array_filter($data['components'],static fn(array $r):bool=>$r['component']===$component))),'version','n',$component,$v->t('data_table')) ?></section><?php endforeach ?><section class="card"><h2><?= $v->e($v->t('advisories')) ?></h2><p><?= $v->e($v->t('unknown_affected')) ?></p><?= $v->table($data['advisories']) ?><a href="/advisories"><?= $v->e($v->t('advisories')) ?></a></section>
<?php elseif ($kind==='downloads'): ?><p class="muted"><?= $v->e($v->t('checks_not_downloads')) ?></p><?php foreach (array_unique(array_column($data['series'],'source')) as $source): ?><section class="card"><h2><?= $v->e($source) ?></h2><?= \FluxFiles\LicenseServer\Admin\Svg::stackedBar(array_map(static fn(array $r):array=>$r+['plan'=>$r['module']],array_values(array_filter($data['series'],static fn(array $r):bool=>$r['source']===$source))),'day','n',$source,$v->t('data_table')) ?></section><?php endforeach ?><section class="card"><?= $v->table($data['versions']) ?><h2><?= $v->e($v->t('update_checks')) ?></h2><?= $v->table($data['checks']) ?></section>
<?php elseif ($kind==='growth'): ?><p><a class="button" href="<?= $v->e($data['analytics_url']) ?>" target="_blank" rel="noreferrer noopener">Cloudflare Web Analytics ↗</a></p><?php foreach ($data['subjects'] as $subject): ?><section class="card"><h2><?= $v->e($subject['source'].' · '.$subject['subject'].' · '.$subject['metric']) ?></h2><?= \FluxFiles\LicenseServer\Admin\Svg::sparkline(array_values(array_filter($data['series'],static fn(array $r):bool=>$r['source']===$subject['source'] && $r['subject']===$subject['subject'] && $r['metric']===$subject['metric'])),'day','value',$subject['subject'],$v->t('data_table')) ?></section><?php endforeach ?>
<?php elseif ($kind==='demo'): ?><section class="card"><?= \FluxFiles\LicenseServer\Admin\Svg::line($data['series'],'day','sandboxes_created',$v->t('demo'),$v->t('data_table')) ?><?= $v->table($data['series']) ?><?php if ($data['budget_bytes']>0 && $data['series']): ?><?php $last=end($data['series']); ?><label><?= $v->e($v->t('uploads_budget')) ?><progress max="<?= $v->e($data['budget_bytes']) ?>" value="<?= $v->e(min($data['budget_bytes'],$last['uploads_bytes'])) ?>"><?= $v->e($last['uploads_bytes']) ?></progress></label><p><?= $v->e($last['uploads_bytes']) ?> / <?= $v->e($data['budget_bytes']) ?> bytes</p><?php endif ?></section>
<?php else: ?><p class="warning"><?= $v->e($v->t('anomalies_caveat')) ?></p><section class="card"><h2><?= $v->e($v->t('thresholds')) ?></h2><?= $v->table([$data['thresholds']]) ?></section><?php foreach (['spread','refresh','unknown','guessing','signatures'] as $metric): ?><section class="card"><h2><?= $v->e($v->t($metric)) ?></h2><?= $v->table($data[$metric]) ?></section><?php endforeach ?><?php endif ?>
